<?php
// Uploads are drafts until their reviewed contents are explicitly confirmed.
function order_review_rows($platform,$path){
 $rows=XlsxReader::rows($path);$cols=order_file_columns($rows,$platform);$hr=$cols['header'];$out=[];
 foreach(array_slice($rows,$hr+1) as $i=>$r){if(!array_filter($r,fn($x)=>trim($x)!==''))continue;$item=trim($r[$cols['item']]??'');if($item===''&&$platform==='Shopee'&&$cols['variation']!==null)$item=trim($r[$cols['variation']]??'');$rawDate=trim($r[$cols['date']]??'');$out[]=['row'=>$hr+$i+2,'date'=>$rawDate!==''&&(is_numeric($rawDate)||strtotime($rawDate)!==false)?excel_date($rawDate):$rawDate,'order'=>trim($r[$cols['order']]??''),'item'=>$item,'external_id'=>trim($r[$cols['item']]??''),'qty'=>$cols['qty']===null?'1':trim($r[$cols['qty']]??''),'product_id'=>null];}
 if(!$out)throw new Exception('No order rows found.');return $out;
}
function order_review_analysis($platform,$rows){
 $errors=[];$unmapped=0;$checked=[];$groups=[];$names=[];$units=0;
 foreach($rows as $r){$r['errors']=[];$r['order']=trim((string)($r['order']??''));$r['item']=trim((string)($r['item']??''));
  if($r['order']===''||strlen($r['order'])>100)$r['errors'][]='Order ID is required (up to 100 characters).';if($r['item']===''||strlen($r['item'])>255)$r['errors'][]='Product description is required (up to 255 characters).';
  $d=DateTime::createFromFormat('!Y-m-d',(string)($r['date']??''));if(!$d||$d->format('Y-m-d')!==($r['date']??''))$r['errors'][]='Enter a valid order date.';
  try{$r['qty']=whole_number($r['qty']??'','Quantity',1);$units+=$r['qty'];}catch(Throwable $e){$r['errors'][]=$e->getMessage();}
  $r['product_name']='';$components=[];try{$components=bundle_review_components($platform,$r);$r['components']=$components;$r['product_id']=$components[0]['product_id'];$labels=[];foreach($components as $c){$p=active_product($c['product_id']);$names[$p['id']]=$p['name'];$labels[]=$p['name'].' × '.$c['per_bundle'];}$r['product_name']=implode(' + ',$labels);}catch(Throwable $e){$r['errors'][]=$e->getMessage();if(str_contains($e->getMessage(),'Unmapped'))$unmapped++;}
  if(!$r['errors']){foreach($components as $c){$pid=$c['product_id'];$deduct=(float)$r['qty']*$c['per_bundle'];if($deduct>2147483647){$r['errors'][]='Bundle quantity exceeds the supported limit.';break;}$key=hash('sha256',strtolower($platform).'|'.$r['order'].'|'.$pid);$line=$r;$line['product_id']=$pid;$line['qty']=(int)$deduct;if(isset($groups[$key])){$sum=$groups[$key]['qty']+$line['qty'];if($sum>2147483647){$r['errors'][]='Grouped order quantity exceeds the supported limit.';break;}$groups[$key]['qty']=$sum;}else $groups[$key]=$line;}}
  foreach($r['errors'] as $error)$errors[]='Row '.$r['row'].': '.$error;
  $checked[]=$r;
 }
 $duplicates=[];$warnings=[];$stock=[];$allocated=[];$platformStock=[];$preview=[];
 foreach($groups as $key=>$line){$pid=$line['product_id'];$q=db()->prepare("SELECT COUNT(*) FROM outflows WHERE reversed_by_request IS NULL AND (dedupe_key=? OR (platform=? AND order_id=? AND product_id=? AND type='Order'))");$q->execute([$key,$platform,$line['order'],$pid]);$duplicate=(bool)$q->fetchColumn();
  if(!isset($stock[$pid])){$s=stock_row($pid);$stock[$pid]=(int)$s['current'];$allocated[$pid]=(int)$s['allocated'];$platformStock[$pid]=platform_qty($platform,$pid);}
  $before=$stock[$pid];$after=$duplicate?$before:$before-$line['qty'];$nextPlatform=$duplicate?$platformStock[$pid]:$platformStock[$pid]-$line['qty'];$nextAllocated=$allocated[$pid]-$platformStock[$pid]+$nextPlatform;
  $entry=['key'=>$key,'order'=>$line['order'],'item'=>$line['item'],'product_name'=>$names[$pid],'product_id'=>$pid,'qty'=>$line['qty'],'date'=>$line['date'],'before'=>$before,'after'=>$after,'allocated_after'=>$nextAllocated,'platform_before'=>$platformStock[$pid],'platform_after'=>$nextPlatform,'duplicate'=>$duplicate];$preview[]=$entry;
  if($duplicate)$duplicates[]=$entry;else{if($after<0||$nextPlatform<0||$nextAllocated!==$after)$warnings[]=$entry+['shortage'=>max(0,-$after),'allocation_gap'=>max(0,$nextAllocated-$after)];$stock[$pid]=$after;$platformStock[$pid]=$nextPlatform;$allocated[$pid]=$nextAllocated;}
 }
 $analysis=['rows'=>$checked,'errors'=>$errors,'unmapped'=>$unmapped,'units'=>$units,'groups'=>$preview,'duplicate_details'=>$duplicates,'stock_warnings'=>$warnings];$analysis['digest']=hash('sha256',json_encode([$platform,$checked,$preview]));return $analysis;
}
function stage_order_upload($platform,$file,$uid){
 if(!in_array($platform,['Shopee','Lazada','TikTok'],true))throw new Exception('Invalid platform.');$pdo=db();$stored=store_upload($file,'order_imports/'.$platform,'ORD');
 $pdo->prepare("INSERT INTO import_batches(platform,import_type,filename,stored_path,status,user_id) VALUES(?,'Orders',?,?,'Review',?)")->execute([$platform,basename($file['name']),$stored,$uid]);$bid=(int)$pdo->lastInsertId();
 try{$rows=order_review_rows($platform,__DIR__.'/'.$stored);$a=order_review_analysis($platform,$rows);$result=['review_version'=>1,'review_revision'=>1,'review_rows'=>$rows];$pdo->prepare('UPDATE import_batches SET rows_read=?,units=?,unmapped_count=?,duplicate_count=?,error_count=?,error_json=?,result_json=? WHERE id=?')->execute([count($rows),$a['units'],$a['unmapped'],count($a['duplicate_details']),count($a['errors']),json_encode($a['errors']),json_encode($result),$bid]);audit('Review order upload','Import',(string)$bid,'Uploaded for review; no inventory posted.');return [$bid,0,$a['unmapped'],count($a['duplicate_details']),$a['errors'],count($a['stock_warnings'])];}
 catch(Throwable $e){$pdo->prepare("UPDATE import_batches SET status='Unsuccessful',error_count=1,error_json=? WHERE id=?")->execute([json_encode([$e->getMessage()]),$bid]);return [$bid,0,0,0,[$e->getMessage()],0];}
}
function order_review_batch($id,$lock=false){$q=db()->prepare('SELECT * FROM import_batches WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute([(int)$id]);$b=$q->fetch();if(!$b||$b['import_type']!=='Orders')throw new Exception('Order upload not found.');return $b;}
// Keep an invalid saved row open; otherwise advance in upload order and wrap.
function order_review_next_correction($analysis,$savedRow){
 $first=0;$passedSaved=false;
 foreach($analysis['rows'] as $row){$id=(int)$row['row'];if($id===(int)$savedRow){if(!empty($row['errors']))return $id;$passedSaved=true;continue;}if(empty($row['errors']))continue;if(!$first)$first=$id;if($passedSaved)return $id;}
 return $first;
}
function save_order_review_row($id,$rowNo,$input,$revision){
 $pdo=db();$pdo->beginTransaction();try{$b=order_review_batch($id,true);$res=json_decode($b['result_json']??'[]',true)?:[];if($b['status']!=='Review'||empty($res['review_version']))throw new Exception('Only pending order uploads can be edited.');if((int)($res['review_revision']??0)!==(int)$revision)throw new Exception('The review changed. Refresh before saving.');$found=false;
 foreach($res['review_rows'] as &$r)if((int)$r['row']===(int)$rowNo){$beforeRow=$r;foreach(['order','date','qty'] as $key)$r[$key]=trim((string)($input[$key]??''));$r['components']=bundle_components_validate($input['components']??[['product_id'=>$input['product_id']??0,'per_bundle'=>1]]);$r['product_id']=$r['components'][0]['product_id'];if(!empty($input['save_bundle'])){if($r['item']===''||strlen($r['item'])>255)throw new Exception('A valid platform description is required for bundle mapping.');bundle_mapping_save($b['platform'],$r['item'],$r['components']);}if($r['item']===''&&$r['product_id']>0)$r['item']=active_product($r['product_id'])['name'];$res['review_changes'][]=['row'=>$rowNo,'before'=>$beforeRow,'after'=>$r,'user_id'=>current_user()['id'],'at'=>date('Y-m-d H:i:s')];$found=true;break;}unset($r);if(!$found)throw new Exception('Review row not found.');$a=order_review_analysis($b['platform'],$res['review_rows']);$res['review_revision']++;$pdo->prepare('UPDATE import_batches SET units=?,unmapped_count=?,duplicate_count=?,error_count=?,error_json=?,result_json=? WHERE id=?')->execute([$a['units'],$a['unmapped'],count($a['duplicate_details']),count($a['errors']),json_encode($a['errors']),json_encode($res),$id]);audit('Correct order review','Import',(string)$id,'Row '.$rowNo.' corrected; no inventory posted.');$pdo->commit();return $a;}
 catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function cancel_order_review($id,$uid){
 $pdo=db();$pdo->beginTransaction();try{$b=order_review_batch($id,true);$res=json_decode($b['result_json']??'[]',true)?:[];
 if($b['status']==='Cancelled'){$pdo->commit();return $b;}
 if($b['status']!=='Review'||empty($res['review_version']))throw new Exception('Only pending order uploads can be cancelled. Posted transactions cannot be cancelled here.');
 $q=$pdo->prepare('SELECT COUNT(*) FROM outflows WHERE import_batch_id=?');$q->execute([$id]);if($q->fetchColumn())throw new Exception('This upload has posted transactions and cannot be cancelled.');
 $res['cancelled_by']=(int)$uid;$res['cancelled_name']=current_user()['name'];$res['cancelled_at']=date('Y-m-d H:i:s');$res['review_revision']=(int)($res['review_revision']??0)+1;
 $pdo->prepare("UPDATE import_batches SET status='Cancelled',result_json=? WHERE id=?")->execute([json_encode($res),$id]);audit('Cancel order upload','Import',(string)$id,$b['platform'].': pending upload cancelled; no inventory deducted.');$pdo->commit();return $b;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function order_cancel_form($id){return '<form method="post" action="actions.php" data-confirm="Cancel this pending upload? No inventory will be deducted. The file will remain in history as Cancelled."><input type="hidden" name="action" value="cancel_order_review"><input type="hidden" name="batch_id" value="'.(int)$id.'"><input type="hidden" name="return" value="order_review&id='.(int)$id.'"><button class="btn ghost" type="submit">Cancel Upload</button></form>';}
function confirm_order_review($id,$digest,$uid){
 $pdo=db();$pdo->beginTransaction();try{$b=order_review_batch($id,true);$res=json_decode($b['result_json']??'[]',true)?:[];if($b['status']!=='Review'||empty($res['review_rows']))throw new Exception('This upload is already posted or is not ready for review.');
 $a=order_review_analysis($b['platform'],$res['review_rows']);if($a['errors'])throw new Exception('Resolve every error and unmapped item before submitting.');
 $ids=array_unique(array_column($a['groups'],'product_id'));sort($ids,SORT_NUMERIC);$lock=$pdo->prepare('SELECT id FROM products WHERE id=? FOR UPDATE');foreach($ids as $pid){$lock->execute([$pid]);$lock->fetchColumn();check_platform_alignment($pid);}
 $a=order_review_analysis($b['platform'],$res['review_rows']);if($a['errors'])throw new Exception('The products changed. Refresh the review.');if(!hash_equals($a['digest'],(string)$digest))throw new Exception('Stock, mappings or duplicates changed since review. Refresh and review the updated balances before confirming.');
 $posted=0;$insert=$pdo->prepare('INSERT INTO outflows(txn_date,platform,order_id,product_id,source_item,qty,type,import_batch_id,dedupe_key,user_id) VALUES(?,?,?,?,?,?,?,?,?,?)');
 foreach($a['groups'] as $line){if($line['duplicate'])continue;$insert->execute([$line['date'],$b['platform'],$line['order'],$line['product_id'],$line['item'],$line['qty'],'Order',$id,$line['key'],$uid]);change_platform_stock($b['platform'],$line['product_id'],-(int)$line['qty'],$line['order'],$line['date']);$posted++;}
 $res['posted_component_rows']=$a['rows'];$res['posted_groups']=$a['groups'];$res['stock_warnings']=$a['stock_warnings'];$res['duplicate_details']=$a['duplicate_details'];$res['dispatch_confirmed']=true;$res['submitted_by']=$uid;$res['submitted_at']=date('Y-m-d H:i:s');$res['confirmed_digest']=$digest;
 $pdo->prepare("UPDATE import_batches SET status='Complete',imported_count=?,unmapped_count=0,duplicate_count=?,error_count=0,error_json='[]',result_json=? WHERE id=?")->execute([$posted,count($a['duplicate_details']),json_encode($res),$id]);audit('Confirm order upload','Import',(string)$id,$b['platform'].': '.$posted.' posted; '.count($a['duplicate_details']).' duplicates skipped; '.count($a['stock_warnings']).' stock warnings.');$pdo->commit();return [$posted,count($a['duplicate_details']),count($a['stock_warnings'])];
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function order_review_uploaded_fields($row){
 $order=trim((string)($row['order']??''));$orderField=$order!==''&&strlen($order)<=100?'<input type="hidden" name="order" value="'.e($order).'">':'<label>Correct uploaded Order ID<input name="order" maxlength="100" required></label>';

 $date=(string)($row['date']??'');$parsed=DateTime::createFromFormat('!Y-m-d',$date);$dateValid=$parsed&&$parsed->format('Y-m-d')===$date;
 $qty=(string)($row['qty']??'');try{whole_number($qty,'Uploaded quantity',1);$qtyValid=true;}catch(Throwable $e){$qtyValid=false;}
 // Normal uploads retain these source values without duplicate editable controls.
 $out=$dateValid?'<input type="hidden" name="date" value="'.e($date).'">':'<label>Correct uploaded date<input type="date" name="date" required></label>';
 return $orderField.$out.($qtyValid?'<input type="hidden" name="qty" value="'.e($qty).'">':'<label>Correct uploaded quantity<input type="number" name="qty" min="1" step="1" required></label>');
}
function order_review_page($b){usability_journey($b['status'],'Order quantities and bundle components deduct sellable stock from the selected order platform. Review item matches and quantities below.','?page=imports&history=all&import_type=Orders');
 $res=json_decode($b['result_json']??'[]',true)?:[];echo '<div class="page-head"><div><a class="back" href="?page=outflow&platform='.e($b['platform']).'">← Outflow</a><h1>Order Upload Review</h1><p>'.e($b['platform']).' · '.e($b['filename']).' · Batch #'.(int)$b['id'].'</p></div><a class="btn ghost" target="_blank" href="download.php?type=original_preview&id='.(int)$b['id'].'">View Original File</a></div>';
 if($b['status']==='Cancelled'){echo '<div class="alert info"><b>Upload Cancelled</b><p>No inventory was deducted. Cancelled by '.e($res['cancelled_name']??'').' on '.e($res['cancelled_at']??'').'. The original file remains in history. To process it later, upload it again.</p></div>';return;}
 if($b['status']==='Review'&&can_action('cancel_order_review'))echo '<div class="card modal-actions">'.order_cancel_form($b['id']).'</div>';
 if(empty($res['review_rows'])){echo '<div class="alert danger">'.e(implode(' · ',json_decode($b['error_json']??'[]',true)?:['Upload the corrected file again.'])).'</div>';return;}
 if($b['status']!=='Review'){echo '<div class="alert success">This upload is already submitted. <a href="?page=outflow_batch&id='.(int)$b['id'].'">View posted details</a></div>';return;}
 $a=order_review_analysis($b['platform'],$res['review_rows']);$final=($_GET['step']??'')==='confirm'&&!$a['errors'];$editable=can_action('save_order_review');
 echo '<div class="tabs"><a class="tab '.(!$final?'active':'').'" href="?page=order_review&id='.(int)$b['id'].'">Review Uploaded File</a>';if(!$a['errors'])echo '<a class="tab '.($final?'active':'').'" href="?page=order_review&id='.(int)$b['id'].'&step=confirm">Final Confirmation</a>';echo '</div><div class="alert info">No inventory has been deducted for this upload. Duplicates will be skipped; negative stock is allowed after confirmation.</div><div class="mini-kpis">';foreach(['File Rows'=>count($a['rows']),'Errors'=>count($a['errors']),'Unmapped'=>$a['unmapped'],'Duplicates'=>count($a['duplicate_details']),'Stock Warnings'=>count($a['stock_warnings'])] as $label=>$count)echo '<div><span>'.e($label).'</span><strong>'.$count.'</strong></div>';echo '</div>';
 if(!$final&&$editable){echo '<div class="card"><div class="card-head"><div><h3>Submit Uploaded Orders</h3><p class="muted">Review first. Submit opens the final summary; only Confirm Outflow deducts inventory.</p></div>';if($a['errors'])echo '<button type="button" class="btn primary" disabled aria-disabled="true">Submit for Final Confirmation</button>';else echo '<a class="btn primary" href="?page=order_review&id='.(int)$b['id'].'&step=confirm">Submit for Final Confirmation</a>';echo '</div>';if($a['errors'])echo '<div class="alert warn">Submit is unavailable: '.count($a['errors']).' validation issue(s) remain. Open Needs Correction, then Edit / Correct and Save &amp; Validate. No inventory has been deducted.</div><a class="btn secondary sm" href="?page=order_review&id='.(int)$b['id'].'&rows=errors">Open Needs Correction</a>';else echo '<p class="muted">All rows are validated. You can submit for final review. Inventory is still unchanged.</p>';echo '</div>';}
 if(!$final){$errorsOnly=($_GET['rows']??'')==='errors';$openCorrection=$errorsOnly?(int)($_GET['open_row']??0):0;$displayRows=$errorsOnly?array_filter($a['rows'],fn($r)=>!empty($r['errors'])):$a['rows'];echo '<div class="card table-wrap"><div class="card-head"><h3>Uploaded Items &amp; Corrections</h3><div><a class="btn ghost sm" href="?page=order_review&id='.(int)$b['id'].'">All Rows</a><a class="btn secondary sm" href="?page=order_review&id='.(int)$b['id'].'&rows=errors">Needs Correction ('.count(array_filter($a['rows'],fn($r)=>!empty($r['errors']))).')</a></div></div><table class="table"><tr><th>Row</th><th>Uploaded Product</th><th>Order / Qty</th><th>Validation</th><th>Correction</th></tr>';
 foreach($displayRows as $r){$openThis=$errorsOnly&&$openCorrection===(int)$r['row']&&!empty($r['errors']);echo '<tr id="order-correction-'.(int)$r['row'].'" style="scroll-margin-top:100px"><td>'.(int)$r['row'].'</td><td><b>'.e($r['item']).'</b><div class="muted">'.e($r['product_name']).'</div></td><td>'.e($r['order']).'<br>'.e($r['qty']).' pcs</td><td>'.($r['errors']?'<div class="alert warn">'.e(implode(' · ',$r['errors'])).'</div>':'<span class="badge ok">Validated</span>').'</td><td>';if($editable){echo '<details class="order-correction-editor"'.($openThis?' open':'').'><summary class="btn secondary sm">Edit / Correct</summary><form method="post" action="actions.php" class="stack"><input type="hidden" name="action" value="save_order_review"><input type="hidden" name="batch_id" value="'.(int)$b['id'].'"><input type="hidden" name="row_no" value="'.(int)$r['row'].'"><input type="hidden" name="revision" value="'.(int)$res['review_revision'].'"><input type="hidden" name="review_rows_view" value="'.($errorsOnly?'errors':'all').'"><input type="hidden" name="return" value="order_review&id='.(int)$b['id'].($errorsOnly?'&amp;rows=errors&amp;open_row='.(int)$r['row'].'#order-correction-'.(int)$r['row']:'').'">'.bundle_editor($r).''.order_review_uploaded_fields($r).'<button class="btn secondary sm">Save &amp; Validate</button></form></details>';}echo '</td></tr>';}
 echo '</table></div>';}
 if($final&&$a['stock_warnings']){echo '<div class="alert warn"><b>Stock warning: '.count($a['stock_warnings']).' order(s) need balance review.</b><p>Negative source-platform stock is allowed and will be recorded in history after confirmation.</p><ul>';foreach($a['stock_warnings'] as $w)echo '<li>'.e($w['order']).' · '.e($w['product_name']).' · '.e($b['platform']).' '.(int)$w['platform_before'].' → '.(int)$w['platform_after'].' pcs; total stock '.(int)$w['before'].' → '.(int)$w['after'].' pcs.</li>';echo '</ul></div>';}
 if($final)order_items_to_deduct($a,$b['platform']);
 if($final){echo '<div class="card table-wrap"><h3>Final Order Summary</h3><table class="table"><tr><th>Order ID</th><th>Matched Product</th><th>Qty</th><th>Before</th><th>After</th><th>Result</th></tr>';foreach($a['groups'] as $r)echo '<tr><td>'.e($r['order']).'</td><td>'.e($r['product_name']).'</td><td>'.(int)$r['qty'].'</td><td>'.(int)$r['before'].'</td><td><b>'.(int)$r['after'].'</b></td><td>'.($r['duplicate']?'Duplicate — skip':($r['after']<0?'Post — negative stock':'Ready to post')).'</td></tr>';echo '</table><p class="muted">Balances are estimates after this file is submitted. Other platform allocations remain unchanged. Stock changes after review require a refreshed confirmation.</p></div>';}
 if($editable&&$final)echo '<div class="card"><form method="post" action="actions.php" data-confirm="Confirm this reviewed order upload? New orders will deduct stock; duplicates will be skipped."><input type="hidden" name="action" value="confirm_order_review"><input type="hidden" name="batch_id" value="'.(int)$b['id'].'"><input type="hidden" name="review_digest" value="'.e($a['digest']).'"><input type="hidden" name="return" value="order_review&id='.(int)$b['id'].'"><label class="ack"><input type="checkbox" name="review_ack" value="1" required> I confirm these orders are already dispatched and cancelled orders were removed. I reviewed products, quantities, duplicates and projected balances, including negative stock.</label><div class="modal-actions"><a class="btn secondary" href="?page=order_review&id='.(int)$b['id'].'">Back to Review</a><button class="btn primary">Confirm Outflow</button></div></form></div>';
}
